from z3 import *

n = 9
E = [[Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]

s = Solver()

for i in range(n):
    s.add(Not(E[i][i]))
    for j in range(i + 1, n):
        s.add(E[i][j] == E[j][i])

degrees = [Sum([If(E[i][j], 1, 0) for j in range(n)]) for i in range(n)]
for i in range(n):
    s.add(degrees[i] >= 2)
    s.add(degrees[i] <= 4)

num_edges = Sum([If(E[i][j], 1, 0) for i in range(n) for j in range(i + 1, n)])
s.add(num_edges >= 11)
s.add(num_edges <= 17)

C = [Int(f"c_{i}") for i in range(n)]
for i in range(n):
    s.add(C[i] >= 0, C[i] <= 2)

for i in range(n):
    for j in range(i + 1, n):
        s.add(Implies(E[i][j], C[i] != C[j]))

s.add(And(E[0][1], E[1][2], E[0][2]))

if s.check() == sat:
    m = s.model()
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if is_true(m[E[i][j]]):
                edges.append((i, j))
    print(edges)
else:
    print("UNSAT")

import networkx as nx
import random

def find_graph():
    for _ in range(10000):
        G = nx.Graph()
        G.add_nodes_from(range(9))

        # Add a triangle to ensure chromatic number >= 3
        G.add_edges_from([(0,1), (1,2), (0,2)])

        # Add random edges
        num_edges = random.randint(11, 17)
        edges_added = 3

        possible_edges = [(u, v) for u in range(9) for v in range(u+1, 9) if not G.has_edge(u, v)]
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if edges_added >= num_edges:
                break
            if G.degree(u) < 4 and G.degree(v) < 4:
                G.add_edge(u, v)
                edges_added += 1

        # Check min degree
        if min(dict(G.degree()).values()) < 2:
            continue

        # Check max degree
        if max(dict(G.degree()).values()) > 4:
            continue

        # Check chromatic number <= 3
        # Since we have a triangle, if it's 3-colorable, chromatic number is exactly 3
        d = nx.coloring.greedy_color(G, strategy='largest_first')
        if max(d.values()) <= 2: # colors are 0, 1, 2
            # verify it's a valid coloring
            valid = True
            for u, v in G.edges():
                if d[u] == d[v]:
                    valid = False
                    break
            if valid:
                return list(G.edges())

    return None

res = find_graph()
if res:
    print(sorted([tuple(sorted(e)) for e in res]))
else:
    print("Not found")
